// Creates the dreamUniversityTracks table — one row per (user, country,
// university) added to a Build Your Dream country's "My Universities" list.
// Same raw-SQL approach as every other migrate-*.mjs.
//
// Usage: node --env-file=.env.local scripts/migrate-add-dream-university-tracks.mjs

import { neon } from '@neondatabase/serverless'

const sql = neon(process.env.DATABASE_URL)

await sql`
  CREATE TABLE IF NOT EXISTS "dreamUniversityTracks" (
    "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    "userId" uuid NOT NULL,
    "country" text NOT NULL,
    "universityId" integer NOT NULL,
    "universityName" text NOT NULL,
    "strengths" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "weaknesses" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "tasks" jsonb NOT NULL DEFAULT '[]'::jsonb,
    "taskProgress" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "createdAt" timestamp NOT NULL DEFAULT now(),
    "updatedAt" timestamp NOT NULL DEFAULT now()
  )
`
await sql`CREATE UNIQUE INDEX IF NOT EXISTS "dreamUniversityTracks_user_country_university_idx" ON "dreamUniversityTracks" ("userId", "country", "universityId")`

console.log('Created dreamUniversityTracks table.')
